func sample_position(a: Vector2, b: Vector2, ratio: float) -> Vector2:
	return a.lerp(b,clampf(ratio,0.0,1.0))

func _ready() -> void:
	$Player.position = sample_position(Vector2(100,180),Vector2(300,180),0.5)
	$Status.text = "Snapshot X: " + str($Player.position.x)

