compute-shaders.solution:
extends Node2D

func double_buffer(values: PackedFloat32Array) -> PackedFloat32Array:
	var output = values.duplicate()
	for i in range(output.size()):
		output[i] *= 2.0
	return output

func _ready() -> void:
	var result = double_buffer(PackedFloat32Array([1,2,3,4]))
	var bytes = result.to_byte_array()
	set_meta("bytes",bytes)
	$Status.text = "Float32 bytes: " + str(bytes.size())
	print(result)

